begin;
create temporary table digest_assertions(label text,passed boolean,detail text);
alter table digest_assertions enable row level security;
create policy temporary_assertions on digest_assertions for all to anon,authenticated using(true) with check(true);
grant select,insert on digest_assertions to authenticated,anon;
do $$begin execute format('grant usage on schema %I to authenticated,anon',(select nspname from pg_namespace where oid=pg_my_temp_schema()));end$$;
create function pg_temp.ok(value boolean,label text) returns boolean language plpgsql as $$begin insert into pg_temp.digest_assertions values(label,coalesce(value,false),null);return value;end$$;
create function pg_temp.denied(command text,expected text,label text) returns boolean language plpgsql as $$declare code text:='00000';detail text;begin begin execute command;exception when others then get stacked diagnostics code=returned_sqlstate,detail=message_text;end;insert into pg_temp.digest_assertions values(label,code=expected,case when code<>expected then code||':'||coalesce(detail,'No error')end);return code=expected;end$$;
insert into auth.users(id,email) values('a9300000-0000-0000-0000-000000000001','digest-c1@example.test'),('a9300000-0000-0000-0000-000000000002','digest-c2@example.test'),('a9300000-0000-0000-0000-000000000003','digest-staff@example.test');
insert into vb_private.staff_members(user_id) values('a9300000-0000-0000-0000-000000000003');
insert into public.vb_clients(id,name,client_type,contact_name,portal_enabled) values('b9300000-0000-0000-0000-000000000001','Digest fixture one','business','Fictional',true),('b9300000-0000-0000-0000-000000000002','Digest fixture two','business','Fictional',true);
insert into public.vb_marks(id,client_id,name,mark_type,status) values('c9300000-0000-0000-0000-000000000001','b9300000-0000-0000-0000-000000000001','EVIDENCE ONE','word','not_filed'),('c9300000-0000-0000-0000-000000000002','b9300000-0000-0000-0000-000000000002','EVIDENCE TWO','word','not_filed');
insert into vb_private.client_memberships(client_id,user_id) values('b9300000-0000-0000-0000-000000000001','a9300000-0000-0000-0000-000000000001'),('b9300000-0000-0000-0000-000000000002','a9300000-0000-0000-0000-000000000002');

insert into vb_private.client_memberships(client_id,user_id) values('b9300000-0000-0000-0000-000000000001','a9300000-0000-0000-0000-000000000002');
insert into public.vb_evidence(id,client_id,mark_id,uploaded_by,kind,captured_on,filename,mime_type,byte_size,content_sha256,object_path,uploaded_at) values('e9300000-0000-0000-0000-000000000001','b9300000-0000-0000-0000-000000000001','c9300000-0000-0000-0000-000000000001','a9300000-0000-0000-0000-000000000001','photo',current_date,'fixture.png','image/png',68,repeat('a',64),'digest-fixture.png',now());

insert into public.vb_bcm_scans(id,client_id,requested_by,settings_version,status,finished_at,snapshot,scan_type) values('e9310000-0000-0000-0000-000000000001','b9300000-0000-0000-0000-000000000001','a9300000-0000-0000-0000-000000000001',1,'completed',now(),'{}','baseline');
insert into public.vb_bcm_scans(id,client_id,requested_by,settings_version,status,finished_at,snapshot,scan_type,baseline_id) values('e9310000-0000-0000-0000-000000000002','b9300000-0000-0000-0000-000000000001','a9300000-0000-0000-0000-000000000001',1,'completed',now(),'{}','comparison','e9310000-0000-0000-0000-000000000001');
select pg_temp.ok(jsonb_array_length(vb_private.digest_items('b9300000-0000-0000-0000-000000000001',array['bcm'],now()-interval '7 days'))=1,'BCM includes completed comparison rather than baseline');
select pg_temp.ok(jsonb_array_length(vb_private.digest_items('b9300000-0000-0000-0000-000000000001',array['bcm'],now()+interval '1 day'))=0,'BCM respects digest period');
insert into vb_private.maintenance_drafts(id,client_id,mark_id,description,window_start,window_end,deadline,next_step,status,verification_source,created_by,updated_by) values('e9320000-0000-0000-0000-000000000001','b9300000-0000-0000-0000-000000000001','c9300000-0000-0000-0000-000000000001','Fictional published date',current_date,current_date+20,current_date+10,'Fictional next step','Upcoming','Fictional verification','a9300000-0000-0000-0000-000000000003','a9300000-0000-0000-0000-000000000003');
insert into public.vb_maintenance_publications(id,client_id,mark_id,description,window_start,window_end,deadline,next_step,status,draft_revision,verified_at) values('e9320000-0000-0000-0000-000000000001','b9300000-0000-0000-0000-000000000001','c9300000-0000-0000-0000-000000000001','Fictional published date',current_date,current_date+20,current_date+10,'Fictional next step','Upcoming',1,now());
select pg_temp.ok(jsonb_array_length(vb_private.digest_items('b9300000-0000-0000-0000-000000000001',array['maintenance'],now()-interval '7 days'))=1,'Published upcoming maintenance included');
update public.vb_maintenance_publications set deadline=current_date+45 where id='e9320000-0000-0000-0000-000000000001';
select pg_temp.ok(jsonb_array_length(vb_private.digest_items('b9300000-0000-0000-0000-000000000001',array['maintenance'],now()-interval '7 days'))=0,'Far future maintenance excluded');
update public.vb_maintenance_publications set deadline=current_date+10,status='Completed' where id='e9320000-0000-0000-0000-000000000001';
select pg_temp.ok(jsonb_array_length(vb_private.digest_items('b9300000-0000-0000-0000-000000000001',array['maintenance'],now()-interval '7 days'))=0,'Completed maintenance excluded');
update public.vb_maintenance_publications set status='Upcoming',withdrawn_at=now() where id='e9320000-0000-0000-0000-000000000001';
select pg_temp.ok(jsonb_array_length(vb_private.digest_items('b9300000-0000-0000-0000-000000000001',array['maintenance'],now()-interval '7 days'))=0,'Withdrawn maintenance excluded');

set local role authenticated;
select set_config('request.jwt.claims','{"sub":"a9300000-0000-0000-0000-000000000001","role":"authenticated","aal":"aal1"}',true);
select pg_temp.denied($$select public.vb_save_digest_preferences('b9300000-0000-0000-0000-000000000002',0,'{"categories":["bcm"],"frequency":"weekly","delivery":"account"}')$$,'42501','Cross-client settings denied');
select pg_temp.denied($$select public.vb_save_digest_preferences('b9300000-0000-0000-0000-000000000001',0,'{"categories":["bcm"],"frequency":"weekly","delivery":"email"}')$$,'22023','Email cannot silently activate');
select pg_temp.denied($$select public.vb_save_digest_preferences('b9300000-0000-0000-0000-000000000001',0,'{"categories":["watch"],"frequency":"weekly","delivery":"account"}')$$,'22023','Disconnected Watch excluded');
select pg_temp.denied($$select public.vb_save_digest_preferences('b9300000-0000-0000-0000-000000000001',0,'{"categories":[],"frequency":"weekly","delivery":"account"}')$$,'22023','Empty categories denied');
select public.vb_save_digest_preferences('b9300000-0000-0000-0000-000000000001',0,'{"categories":["use_history"],"frequency":"weekly","delivery":"account"}');
select pg_temp.ok((select version=1 and frequency='weekly' from public.vb_digest_preferences where client_id='b9300000-0000-0000-0000-000000000001'),'Preferences persisted');
select pg_temp.denied($$select public.vb_save_digest_preferences('b9300000-0000-0000-0000-000000000001',0,'{"categories":["bcm"],"frequency":"daily","delivery":"account"}')$$,'40001','Stale save cannot overwrite');
select public.vb_generate_digest_sample('b9300000-0000-0000-0000-000000000001',1);
select pg_temp.ok((select source_items->0->>'source'='use_history' and jsonb_array_length(source_items)=1 from public.vb_inbox),'Selected source only included');
select pg_temp.ok((select read_at is null from public.vb_inbox),'New messages unread');
select pg_temp.ok(jsonb_array_length(public.vb_open_inbox('b9300000-0000-0000-0000-000000000001',(select id from public.vb_inbox))->'items')=1,'Authoritative available upload resolved');
select pg_temp.ok((select read_at is not null from public.vb_inbox),'Opening marks read');
select pg_temp.denied($$insert into public.vb_inbox(recipient_id,client_id,categories,frequency,period_start,source_items) values(auth.uid(),'b9300000-0000-0000-0000-000000000001',array['bcm'],'daily',now(),'[]')$$,'42501','Client cannot forge inbox messages');
select pg_temp.denied($$update public.vb_digest_preferences set frequency='daily'$$,'42501','Direct settings update denied');
reset role;
create temporary table digest_message_id as select id from public.vb_inbox where client_id='b9300000-0000-0000-0000-000000000001';
alter table digest_message_id enable row level security;
create policy temporary_message_fixture on digest_message_id for select to authenticated using(true);
grant select on digest_message_id to authenticated;
update public.vb_evidence set removed_at=now(),removed_by='a9300000-0000-0000-0000-000000000001' where id='e9300000-0000-0000-0000-000000000001';
set local role authenticated;
select pg_temp.ok(jsonb_array_length(public.vb_open_inbox('b9300000-0000-0000-0000-000000000001',(select id from digest_message_id))->'items')=0,'Old digest excludes removed upload');
select set_config('request.jwt.claims','{"sub":"a9300000-0000-0000-0000-000000000002","role":"authenticated","aal":"aal1"}',true);
select pg_temp.ok((select count(*)=0 from public.vb_inbox),'Same-client other member cannot read personal inbox');
select pg_temp.ok((select count(*)=0 from public.vb_digest_preferences),'Same-client other member cannot read preferences');
select pg_temp.denied($$select public.vb_open_inbox('b9300000-0000-0000-0000-000000000001',(select id from digest_message_id))$$,'42501','Same-client other member cannot open digest');
select set_config('request.jwt.claims','{"sub":"a9300000-0000-0000-0000-000000000003","role":"authenticated","aal":"aal2"}',true);
select pg_temp.ok((select count(*)=0 from public.vb_inbox),'Attorney cannot read personal client inbox');
select pg_temp.denied($$select public.vb_generate_digest_sample('b9300000-0000-0000-0000-000000000001',1)$$,'42501','Attorney cannot impersonate recipient');
reset role;
update public.vb_clients set portal_enabled=false where id='b9300000-0000-0000-0000-000000000001';
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"a9300000-0000-0000-0000-000000000001","role":"authenticated","aal":"aal1"}',true);
select pg_temp.ok((select count(*)=0 from public.vb_inbox),'Disabled portal inbox hidden');
select pg_temp.denied($$select public.vb_open_inbox('b9300000-0000-0000-0000-000000000001',(select id from digest_message_id))$$,'42501','Disabled portal open denied');
reset role;
set local role anon;
select pg_temp.denied($$select * from public.vb_inbox$$,'42501','Signed-out inbox read denied');
select pg_temp.denied($$select public.vb_generate_digest_sample('b9300000-0000-0000-0000-000000000001',1)$$,'42501','Signed-out generation denied');
reset role;
select jsonb_build_object('executed',count(*),'all_passed',bool_and(passed),'assertions',jsonb_agg(to_jsonb(a))) as digest_tests from pg_temp.digest_assertions a;
rollback;
